/** One INI layer, refused at its own position when the grammar or the schema rejects it. */
function iniLayer(name, path, strict) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    return fail(`cannot read ${path}`)
  }

  let values
  try {
    values = parseIni(text)
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }

  if (strict) {
    for (const [key, value] of values) {
      if (setting(key) === undefined) {
        return fail(`${path}:${value.line}:${value.column}: unknown setting ${key}`)
      }
    }
  }

  return { name, values }
}

